@pytest.mark.parametrize('kind', ['arm', 'look', 'drive', 'mecanum']) @pytest.mark.parametrize('with_hold', [False, True]) def test_p1_unapplied_hold_cannot_authorize_arm_or_motion_during_reobserve(kind, with_hold): host, exs = setup(factory=m2_controller) assert start(host)['accepted'] ep, own = active(host)['r1'], exs['r1'] own.on_command({'t': 0., 'kind': 'mecanum', 'forward': .1, 'left': 0., 'turn': 0., 'duration_s': .15}) ep.controller.driver.state = 'look_arm' fresh(own, .1, .055) cmd = ({'kind': 'arm', 'servo_id': 6, 'pulse': 1520} if kind == 'arm' else {'kind': 'look', 'pan_pulse': 1520} if kind == 'look' else {'kind': kind, 'forward': .01, 'left': 0., 'turn': 0., 'duration_s': .1}) commands = ([{'kind': 'hold'}] if with_hold else []) + [cmd] assert ep.command_guard.check(.1, commands) == [{'kind': 'hold'}] host._pair_safety(.1) > assert ends(own)[0]['detail']['reason'] == 'POSE_UNCERTAIN' ^^^^^^^^^^^^ E IndexError: list index out of range
